218	    ? allowedHostnamesFromEnvRaw
219	      .split(",")
220	      .map((value) => value.trim().toLowerCase())
221	      .filter((value) => value.length > 0)
222	    : null;
223	  const publicUrlHostname = authPublicBaseUrl
224	    ? (() => {
225	      try {
226	        return new URL(authPublicBaseUrl).hostname.trim().toLowerCase();
227	      } catch {
228	        return null;
229	      }
230	    })()
231	    : null;
232	  const allowedHostnames = Array.from(
233	    new Set(
234	      [
235	        ...(allowedHostnamesFromEnv ?? fileConfig?.server.allowedHostnames ?? []),
236	        ...(publicUrlHostname ? [publicUrlHostname] : []),
237	      ]
